configuration.css:

/* === IMPORTAR FUENTE PROFESIONAL === */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

/* === VARIABLES CSS === */
:root {
    --primary-blue: #1976D2;
    --secondary-blue: #0D47A1;
    --accent-blue: #42A5F5;
    --success-green: #4CAF50;
    --warning-orange: #FF9800;
    --error-red: #F44336;
    --dark-bg: #121212;
    --card-bg: #1E1E1E;
    --text-primary: #FFFFFF;
    --text-secondary: #B0BEC5;
    --border-color: #37474F;
}

/* === TU SOLUCIÓN QUE FUNCIONA (SIN TOCAR) === */
/* Ocultar solo el SPAN del hook, NO todo el step */
div.step[title="AFTER_STEP"] span {
    display: none !important;
    visibility: hidden !important;
    height: 0 !important;
    overflow: hidden !important;
}

/* MANTENER las imágenes del hook */
div.step[title="AFTER_STEP"] .row.mb-3 {
    display: block !important;
    margin: 15px 0 !important;
    padding: 15px !important;
}

/* === BODY Y ESTRUCTURA GENERAL === */
body {
    font-family: 'Inter', 'Segoe UI', Arial, sans-serif !important;
    background: linear-gradient(135deg, #0D47A1 0%, #1976D2 50%, #42A5F5 100%) !important;
    color: var(--text-primary) !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* === HEADER PRINCIPAL (SOLO HACER FIJO) === */
.header.navbar {
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    box-shadow: 0 4px 20px rgba(0,0,0,0.3) !important;
    border-bottom: 3px solid var(--accent-blue) !important;
    position: fixed !important; /* SOLO ESTO - header fijo */
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 1000 !important;
}



/* === NAVEGACIÓN (SIN CAMBIOS EXTRA) === */
.side-nav {
    background: var(--card-bg) !important;
    border-right: 2px solid var(--border-color) !important;
}

.side-nav-menu .nav-item a {
    color: var(--text-secondary) !important;
    transition: all 0.3s ease !important;
}

.side-nav-menu .nav-item a:hover {
    background: var(--primary-blue) !important;
    color: white !important;
}

/* === CONTENEDOR PRINCIPAL (SOLO AGREGAR PADDING-TOP) === */
.main-content {
    background: var(--dark-bg) !important;
    min-height: 100vh !important;
    padding: 20px !important;
    padding-top: 85px !important; /* SOLO ESTO - para el header */
}

/* === DASHBOARD CARDS === */
.card {
    background: linear-gradient(145deg, var(--card-bg), #2A2A2A) !important;
    border: 1px solid var(--border-color) !important;
    border-radius: 12px !important;
    box-shadow: 0 8px 25px rgba(0,0,0,0.2) !important;
    transition: transform 0.3s ease, box-shadow 0.3s ease !important;
}

.card:hover {
    transform: translateY(-2px) !important;
    box-shadow: 0 12px 35px rgba(0,0,0,0.3) !important;
}

.card-header {
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    color: white !important;
    border-radius: 12px 12px 0 0 !important;
    padding: 15px 20px !important;
    font-weight: 600 !important;
}

.card-header h6 {
    color: white !important;
    margin: 0 !important;
    font-size: 16px !important;
}

.card-body {
    background: var(--card-bg) !important;
    color: var(--text-primary) !important;
    padding: 20px !important;
}

/* === ESTADÍSTICAS === */
.card-body h3 {
    color: var(--accent-blue) !important;
    font-weight: 700 !important;
    font-size: 32px !important;
    margin: 10px 0 !important;
    text-shadow: 0 2px 4px rgba(0,0,0,0.3) !important;
}

.card-body p {
    color: var(--text-secondary) !important;
    font-weight: 500 !important;
    margin: 0 !important;
}

.text-pass {
    color: var(--success-green) !important;
    font-weight: 700 !important;
}

.text-fail {
    color: var(--error-red) !important;
    font-weight: 700 !important;
}

/* === LISTA DE TESTS === */
.test-list {
    background: var(--card-bg) !important;
    border-radius: 12px !important;
    border: 1px solid var(--border-color) !important;
}

.test-list-tools {
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    padding: 15px 20px !important;
    border-radius: 12px 12px 0 0 !important;
}

.test-list-tools .tools a {
    color: white !important;
    font-weight: 600 !important;
}

.test-item {
    background: var(--card-bg) !important;
    border-bottom: 1px solid var(--border-color) !important;
    transition: all 0.3s ease !important;
}

.test-item:hover {
    background: linear-gradient(135deg, #2A2A2A, #333333) !important;
}

.test-item.active {
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    border-left: 4px solid var(--accent-blue) !important;
}

.test-detail .name {
    color: var(--text-primary) !important;
    font-weight: 600 !important;
    font-size: 16px !important;
    margin-bottom: 8px !important;
}

.test-detail .text-sm {
    color: var(--text-secondary) !important;
    font-size: 13px !important;
}

/* === BADGES PROFESIONALES === */
.badge {
    border-radius: 20px !important;
    padding: 6px 12px !important;
    font-weight: 600 !important;
    font-size: 11px !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
}

.badge-success {
    background: linear-gradient(135deg, var(--success-green), #388E3C) !important;
    color: white !important;
    box-shadow: 0 3px 10px rgba(76, 175, 80, 0.3) !important;
}

.badge-danger {
    background: linear-gradient(135deg, var(--error-red), #D32F2F) !important;
    color: white !important;
    box-shadow: 0 3px 10px rgba(244, 67, 54, 0.3) !important;
}

.badge-primary {
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    color: white !important;
    box-shadow: 0 3px 10px rgba(25, 118, 210, 0.3) !important;
}

.pass-bg {
    background: linear-gradient(135deg, var(--success-green), #2E7D32) !important;
    color: white !important;
}

/* === CONTENIDO DEL TEST (SIN CAMBIOS EXTRA) === */
.test-content {
    background: var(--card-bg) !important;
    border-radius: 12px !important;
    border: 1px solid var(--border-color) !important;
}

.test-content-detail {
    padding: 20px !important;
}

.detail-head {
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    padding: 20px !important;
    border-radius: 12px !important;
    margin-bottom: 20px !important;
    box-shadow: 0 4px 15px rgba(25, 118, 210, 0.3) !important;
}

.test-status {
    color: white !important;
    font-weight: 700 !important;
    font-size: 24px !important;
    margin-bottom: 10px !important;
}

.test-status::before {
    content: "SCENARIO: " !important;
    margin-right: 10px !important;
    font-weight: 600 !important;
}

/* === ACCORDION Y SCENARIOS === */
.accordion .card {
    background: linear-gradient(145deg, var(--card-bg), #2A2A2A) !important;
    border: 1px solid var(--border-color) !important;
    margin-bottom: 15px !important;
}

.accordion .card-header {
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    padding: 18px 25px !important;
}

.card-title .node {
    color: white !important;
    font-weight: 600 !important;
    font-size: 18px !important;
}

.card-title .node::before {
    content: "TEST: " !important;
    margin-right: 8px !important;
    font-weight: 600 !important;
}

/* === STEPS MEJORADOS === */
.step {
    background: linear-gradient(145deg, #263238, #37474F) !important;
    border-left: 4px solid var(--accent-blue) !important;
    padding: 15px 20px !important;
    margin: 8px 0 !important;
    border-radius: 0 8px 8px 0 !important;
    transition: all 0.3s ease !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.2) !important;
}

.step:hover {
    background: linear-gradient(145deg, #37474F, #455A64) !important;
    transform: translateX(5px) !important;
    box-shadow: 0 4px 15px rgba(0,0,0,0.3) !important;
}

.step.pass-bg {
    border-left-color: var(--success-green) !important;
}

.step span {
    color: var(--text-primary) !important;
    font-weight: 500 !important;
    font-size: 15px !important;
    line-height: 1.5 !important;
}

/* === ICONOS PARA DIFERENTES TIPOS DE STEPS (SIN EMOJI) === */
.step span:first-child::before {
    margin-right: 8px !important;
    font-size: 16px !important;
    font-weight: bold !important;
    color: var(--accent-blue) !important;
}

.step[title*="LoginPageSteps"] span::before {
    content: "LOGIN " !important;
}

.step[title*="BaxterHomeSteps"] span::before {
    content: "HOME " !important;
}

.step[title*="iOpenTheBaxterWebsite"] span::before {
    content: "WEB " !important;
}

.step[title*="iTryToLoginWith"] span::before {
    content: "AUTH " !important;
}

.step[title*="iVerifyLoginWasSuccessful"] span::before {
    content: "CHECK " !important;
}

.step[title*="iSelectTheGroup"] span::before {
    content: "GROUP " !important;
}

.step[title*="iSelectThePatient"] span::before {
    content: "PATIENT " !important;
}

.step[title*="iOpenPDPrescription"] span::before {
    content: "MODULE " !important;
}

/* === SCREENSHOTS MEJORADOS (VISIBLES) === */
.row.mb-3 {
    display: block !important;
    margin: 15px 0 !important;
    padding: 15px !important;
    background: linear-gradient(145deg, #1A1A1A, #2E2E2E) !important;
    border-radius: 12px !important;
    border: 2px solid var(--accent-blue) !important;
    box-shadow: 0 6px 20px rgba(0,0,0,0.3) !important;
}

.row.mb-3::before {
    content: "Evidence Captured" !important;
    display: block !important;
    color: var(--accent-blue) !important;
    font-weight: 700 !important;
    font-size: 14px !important;
    margin-bottom: 10px !important;
    text-align: center !important;
}

.row.mb-3 img {
    display: block !important; /* Forzar que se muestren */
    border-radius: 8px !important;
    border: 3px solid var(--accent-blue) !important;
    box-shadow: 0 4px 15px rgba(0,0,0,0.4) !important;
    transition: transform 0.3s ease !important;
    max-width: 100% !important;
    height: auto !important;
    margin: 0 auto !important;
}

.row.mb-3 img:hover {
    transform: scale(1.05) !important;
    box-shadow: 0 8px 25px rgba(66, 165, 245, 0.4) !important;
}

/* Asegurar que las imágenes dentro de hooks se vean */
div.step[title="AFTER_STEP"] img {
    display: block !important;
    visibility: visible !important;
}

div.step[title="AFTER_STEP"] .row.mb-3 {
    display: block !important;
    visibility: visible !important;
}

/* === TABLAS === */
.table {
    background: var(--card-bg) !important;
    color: var(--text-primary) !important;
    border-radius: 8px !important;
    overflow: hidden !important;
    box-shadow: 0 4px 15px rgba(0,0,0,0.2) !important;
}

.table th {
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    color: white !important;
    font-weight: 600 !important;
    padding: 15px 12px !important;
    border: none !important;
}

.table td {
    background: var(--card-bg) !important;
    color: var(--text-primary) !important;
    padding: 12px !important;
    border-bottom: 1px solid var(--border-color) !important;
}

.table tr:hover td {
    background: linear-gradient(135deg, #2A2A2A, #333333) !important;
}

/* === SCROLLBARS PERSONALIZADOS === */
.scrollable::-webkit-scrollbar {
    width: 8px !important;
    height: 8px !important;
}

.scrollable::-webkit-scrollbar-track {
    background: var(--card-bg) !important;
    border-radius: 4px !important;
}

.scrollable::-webkit-scrollbar-thumb {
    background: linear-gradient(135deg, var(--primary-blue), var(--accent-blue)) !important;
    border-radius: 4px !important;
}

.scrollable::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(135deg, var(--accent-blue), var(--primary-blue)) !important;
}

/* === ANIMACIONES === */
@keyframes slideInUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.step, .card, .test-item {
    animation: slideInUp 0.6s ease-out !important;
}

/* === RESPONSIVE === */
@media (max-width: 768px) {
    .card-body h3 {
        font-size: 24px !important;
    }

    .step {
        padding: 12px 15px !important;
    }

    .test-status {
        font-size: 20px !important;
    }
}

/* === ELEMENTOS ESPECÍFICOS === */
.status-avatar {
    color: var(--accent-blue) !important;
    font-size: 18px !important;
}

.chart-container canvas {
    border-radius: 8px !important;
}

/* === FOOTER IMPLÍCITO === */
.main-content::after {
    content: "Documento Confidencial - VersiaRenal QA Team" !important;
    display: block !important;
    text-align: center !important;
    padding: 20px !important;
    margin-top: 40px !important;
    background: linear-gradient(135deg, var(--primary-blue), var(--secondary-blue)) !important;
    color: white !important;
    border-radius: 12px !important;
    font-size: 14px !important;
    font-weight: 500 !important;
}
